  return !(
    /^o\d+(?:-|$)/i.test(baseId) ||
    (gpt && Number(gpt[1]) >= 5 && !gpt[2]?.toLowerCase().startsWith("chat")) ||
    /(?:^|-)search-preview(?:-|$)/i.test(baseId)
  );
}

