function publicHost(url: URL): string {
  const host = url.hostname.toLowerCase().replace(/\.$/, "");
  if (
    !/^https?:$/.test(url.protocol) ||
    url.username ||
    url.password ||
    url.port ||
    isIP(host.replace(/^\[|\]$/g, "")) ||
    !host.includes(".") ||
    /(?:^|\.)(?:localhost|local|internal|lan|home|localdomain|test|invalid|example|onion)$/.test(
